local Om,Pm=0,0
for Qm,Rm in pairs(Im.Pets or{})do
local Sm=E.PetCfg[Qm]
if Sm and Sm.Power then
Pm=Pm+Rm*Sm.Power
Om=Om+Rm
end
end
if Om<=0 then
return 0,0,Lm,0,0
end
local Tm=Pm/Om
local Um= #Jm<Km and 0 or(Jm[1]or 0)
local Vm,Wm,Xm,Ym=0,0,0,0
for Zm,_m in pairs(Im.Pets or{})do
local an=E.PetCfg[Zm]
local bn=an and tonumber(an.Power)
if bn then
Xm=math.max(Xm,bn)
if bn>Um then
Vm=Vm+_m/Om*(bn-Um)
Wm=Wm+_m/Om
elseif u.craftGolden then
local cn=math.max(0,(3*bn-Um)/6)
if u.craftDiamond then
cn=math.max(cn,(7*bn-Um)/30)
end
if u.craftDiamond and u.rainbow then
cn=math.max(cn,(10*bn-Um)/150)
end
if cn>0 then
Vm=Vm+_m/Om*cn
Ym=Ym+_m/Om
end
end
end
end
return Vm/Lm,Tm,Lm,Wm,Xm,Ym
end
